# Check if this rule explains the DEMO correctly

def check_rule(demo_in, demo_out):
    for r in range(15):
        for c in range(13):
            if demo_in[r][c] == 3:
                # Check all 8 neighbors
                neighbors = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < 15 and 0 <= nc < 13:
                            if demo_in[nr][nc] == 1:
                                neighbors += 1

                if neighbors > 0:
                    expected_out = 1
                else:
                    expected_out = 3

                actual_out = demo_out[r][c]
                if expected_out != actual_out:
                    print(f"Mismatch at ({r},{c}): expected 1, got 3 (neighbors={neighbors})")
                    return False

    print("Rule works! 3→1 if any neighbor is 1")
    return True

check_rule(demo_in, demo_out)

